function CountIntegers(values: seq<object>) : int
    reads values
{
    var count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= count <= |values| // Count must not exceed the size of the input list
        invariant i <= |values| // Index must not exceed the size of the input list
    {
        if values[i] is int {
            count := count + 1;
        }
        i := i + 1;
    }
    count
}
